/*
 * HIJ Search Docs: navigation layer for documentation.ai's classic template.
 *
 * documentation.json already gives the shape natively: the 8 flow sections are root tabs (top tab row), and
 * JS SDKs / Analytics hold nested sidebar dropdowns (menu item -> version) that documentation.ai stacks at the top
 * of the sidebar. This script only adds what the platform has no setting for, and the site works without it:
 *   1. "JS SDKs" and "Analytics" tabs get a chevron and a hover/focus menu of their menu items.
 *   2. Section landings (JS SDKs overview pages, Analytics pages) list the sub-products as sidebar entries
 *      ("Full stack ›", "Headless ›", "GTM template ›") instead of showing the dropdown selector.
 *   3. Inside a sub-product, the two stacked selectors are drawn as one card (CSS, keyed on html.hij-entered),
 *      and JS SDK trees end with a "Next step: analytics" group.
 *   4. Choosing another version (or sub-product) keeps the reader on the matching page when it exists;
 *      documentation.ai itself always opens the target's first page.
 * Navigation data is generated by convert.py from the same NAV that writes documentation.json.
 */
(function () {
  "use strict";
  var DATA = {"products": [{"id": "full-stack", "title": "Full stack", "section": "JS SDKs", "versions": [{"label": "Full stack 3.x", "status": "Latest", "prefix": "/full-stack/", "pages": ["/full-stack/quick-start", "/full-stack/search-results", "/full-stack/search-suggestions", "/full-stack/failover"]}, {"label": "Full stack 2.x", "status": "Legacy", "prefix": "/full-stack/v2/", "pages": ["/full-stack/v2/quick-start", "/full-stack/v2/search-results"]}], "next": true}, {"id": "headless", "title": "Headless", "section": "JS SDKs", "versions": [{"label": "Headless 3.x", "status": "Latest", "prefix": "/headless/", "pages": ["/headless/quick-start", "/headless/collections", "/headless/failover"]}, {"label": "Headless 2.x", "status": "Legacy", "prefix": "/headless/v2/", "pages": ["/headless/v2/quick-start", "/headless/v2/collections"]}], "next": true}, {"id": "gtm-template", "title": "GTM template", "section": "Analytics", "versions": [{"label": "GTM r20260217", "status": "Latest", "prefix": "/analytics/gtm/", "pages": ["/analytics/gtm/setup"]}, {"label": "GTM r20250801", "status": "Legacy", "prefix": "/analytics/gtm/r20250801/", "pages": ["/analytics/gtm/r20250801/setup"]}, {"label": "GTM r20240718", "status": "Legacy", "prefix": "/analytics/gtm/r20240718/", "pages": ["/analytics/gtm/r20240718/setup"]}], "next": false}], "landings": {"JS SDKs": {"pages": ["/sdks/overview", "/sdks/server-side"], "next": true, "entries": [{"title": "Full stack", "href": "/full-stack/quick-start"}, {"title": "Headless", "href": "/headless/quick-start"}]}, "Analytics": {"pages": ["/analytics/overview", "/analytics/shopify-pixel", "/analytics/analytics-api", "/analytics/sdk-manual"], "next": false, "entries": [{"title": "GTM template", "href": "/analytics/gtm/setup"}]}}, "menus": {"JS SDKs": [{"title": "Overview", "description": "Full stack or headless, and the browser-only rule", "href": "/sdks/overview", "pages": ["/sdks/overview", "/sdks/server-side"]}, {"title": "Full stack", "description": "UI widgets SDK, HIJ.UIWidgets.*", "href": "/full-stack/quick-start", "pages": ["/full-stack/quick-start", "/full-stack/search-results", "/full-stack/search-suggestions", "/full-stack/failover", "/full-stack/v2/quick-start", "/full-stack/v2/search-results"]}, {"title": "Headless", "description": "Connector SDK, HIJ.Connector.*", "href": "/headless/quick-start", "pages": ["/headless/quick-start", "/headless/collections", "/headless/failover", "/headless/v2/quick-start", "/headless/v2/collections"]}], "Analytics": [{"title": "Analytics", "description": "Which events, who sends them, and how", "href": "/analytics/overview", "pages": ["/analytics/overview", "/analytics/shopify-pixel", "/analytics/analytics-api", "/analytics/sdk-manual"]}, {"title": "GTM template", "description": "Google Tag Manager tag template releases", "href": "/analytics/gtm/setup", "pages": ["/analytics/gtm/setup", "/analytics/gtm/r20250801/setup", "/analytics/gtm/r20240718/setup"]}]}, "nextStep": {"title": "Next step: analytics", "links": [{"title": "Analytics overview", "href": "/analytics/overview"}]}};
  if (!DATA || window.__hijNav) return;
  window.__hijNav = true;

  var root = document.documentElement;
  var norm = function (p) { p = (p || "/").replace(/\/+$/, ""); return p || "/"; };
  var here = function () { return norm(location.pathname); };
  var pathOf = function (href) { try { return norm(new URL(href, location.href).pathname); } catch (e) { return null; } };

  function versionOf(path) {
    for (var i = 0; i < DATA.products.length; i++) {
      var pr = DATA.products[i];
      for (var j = 0; j < pr.versions.length; j++) {
        if (pr.versions[j].pages.indexOf(path) >= 0) return { product: pr, version: pr.versions[j] };
      }
    }
    return null;
  }
  function landingOf(path) {
    for (var name in DATA.landings) {
      if (DATA.landings[name].pages.indexOf(path) >= 0) return { name: name, landing: DATA.landings[name] };
    }
    return null;
  }
  /** The page at the same place in another version (or sub-product), or null. */
  function project(fromPath, toVersion) {
    var cur = versionOf(fromPath);
    if (!cur) return null;
    var cand = toVersion.prefix + fromPath.slice(cur.version.prefix.length);
    return toVersion.pages.indexOf(cand) >= 0 ? cand : null;
  }

  // ---- 4. same-page switching ------------------------------------------------------------------------------
  // documentation.ai's dropdown items are plain links to the target's first page (a.dai-sidebar-dropdown-item).
  function retarget(anchor) {
    var href = pathOf(anchor.getAttribute("href"));
    var cur = versionOf(here());
    var dest = href && versionOf(href);
    if (!cur || !dest) return null;
    // Icon markup (e.g. a Font Awesome licence comment) can precede the label, so match the label anywhere.
    var text = (anchor.textContent || "").trim();
    var isVersionItem = dest.product === cur.product &&
      dest.product.versions.some(function (v) { return text.indexOf(v.label) >= 0; });
    if (dest.product === cur.product && !isVersionItem) return here(); // the sub-product already open
    return project(here(), dest.version) || href;
  }
  document.addEventListener("click", function (e) {
    if (e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    var a = e.target && e.target.closest && e.target.closest("a.dai-sidebar-dropdown-item");
    if (!a) return;
    var target = retarget(a);
    if (!target || target === pathOf(a.getAttribute("href"))) return; // native behaviour is already right
    e.preventDefault();
    e.stopPropagation();
    if (target !== here()) location.assign(target);
    else document.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })); // close the popover
  }, true);

  // ---- 1. tab menus ------------------------------------------------------------------------------------------
  var panel = null, panelTab = null, closeTimer = null;
  function closeMenu() {
    clearTimeout(closeTimer);
    if (panel) { panel.remove(); panel = null; }
    if (panelTab) { panelTab.setAttribute("aria-expanded", "false"); panelTab = null; }
  }
  function scheduleClose() { clearTimeout(closeTimer); closeTimer = setTimeout(closeMenu, 120); }
  function openMenu(tab) {
    var items = DATA.menus[tab.getAttribute("data-hij-tab")];
    if (!items) return;
    clearTimeout(closeTimer);
    if (panelTab === tab) return;
    closeMenu();
    panel = document.createElement("div");
    panel.className = "hij-menu";
    panel.setAttribute("role", "menu");
    panel.setAttribute("data-hij-menu", tab.getAttribute("data-hij-tab"));
    var path = here();
    items.forEach(function (it) {
      var a = document.createElement("a");
      a.href = it.href;
      a.setAttribute("role", "menuitem");
      a.setAttribute("data-hij-menu-item", it.title);
      if (it.pages.indexOf(path) >= 0) a.setAttribute("aria-current", "page");
      var t = document.createElement("span"); t.className = "hij-menu-title"; t.textContent = it.title;
      var d = document.createElement("span"); d.className = "hij-menu-desc"; d.textContent = it.description;
      a.appendChild(t); a.appendChild(d);
      panel.appendChild(a);
    });
    var r = tab.getBoundingClientRect();
    panel.style.left = Math.max(8, Math.min(r.left - 8, window.innerWidth - 240)) + "px";
    panel.style.top = r.bottom + 4 + "px";
    panel.addEventListener("mouseenter", function () { clearTimeout(closeTimer); });
    panel.addEventListener("mouseleave", scheduleClose);
    document.body.appendChild(panel);
    panelTab = tab;
    tab.setAttribute("aria-expanded", "true");
  }
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && panel) { var t = panelTab; closeMenu(); if (t) t.focus(); }
    if (e.key === "ArrowDown" && panelTab && document.activeElement === panelTab) {
      e.preventDefault(); var first = panel && panel.querySelector("a"); if (first) first.focus();
    }
  });
  document.addEventListener("pointerdown", function (e) {
    if (panel && !panel.contains(e.target) && !(panelTab && panelTab.contains(e.target))) closeMenu();
  });
  window.addEventListener("scroll", function () { if (panel) closeMenu(); }, { passive: true });

  var CHEVRON = '<svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" ' +
    'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';
  function decorateTabs() {
    var links = document.querySelectorAll(".dai-navbar-tabs a");
    for (var i = 0; i < links.length; i++) {
      var a = links[i], name = (a.textContent || "").trim();
      if (!DATA.menus[name] || a.getAttribute("data-hij-tab") === name) continue;
      a.setAttribute("data-hij-tab", name);
      a.setAttribute("aria-haspopup", "menu");
      a.setAttribute("aria-expanded", "false");
      var label = a.querySelector("span") || a;
      if (!label.querySelector(".hij-tab-chevron")) {
        var c = document.createElement("span"); c.className = "hij-tab-chevron"; c.innerHTML = CHEVRON;
        label.appendChild(c);
      }
      a.addEventListener("mouseenter", function () { openMenu(this); });
      a.addEventListener("mouseleave", scheduleClose);
      a.addEventListener("focus", function () { openMenu(this); });
    }
  }

  // ---- 2 + 3. sidebar ------------------------------------------------------------------------------------------
  function group(proto, title, links, key) {
    var wrap = document.createElement("div");
    wrap.className = "dai-sidebar-group hij-group";
    wrap.setAttribute("data-hij-group", key);
    if (title) {
      var h = document.createElement("p");
      h.className = (proto.title && proto.title.className) || "dai-sidebar-group-title";
      h.textContent = title;
      wrap.appendChild(h);
    }
    var ul = document.createElement("ul");
    links.forEach(function (l) {
      var li = document.createElement("li"), a = document.createElement("a");
      a.href = l.href;
      a.className = ((proto.page && proto.page.className) || "dai-sidebar-page") + (l.entry ? " hij-entry" : "");
      var s = document.createElement("span"); s.textContent = l.title; a.appendChild(s);
      if (l.entry) { var c = document.createElement("span"); c.className = "hij-entry-chevron"; c.setAttribute("aria-hidden", "true"); c.textContent = "›"; a.appendChild(c); }
      li.appendChild(a); ul.appendChild(li);
    });
    wrap.appendChild(ul);
    return wrap;
  }
  function decorateSidebar() {
    var path = here(), cur = versionOf(path), land = landingOf(path);
    root.classList.toggle("hij-entered", !!cur);
    root.classList.toggle("hij-landing", !!land);
    // Groups appended after the sidebar's own list: landing entries, then (JS SDK trees) "Next step: analytics".
    var specs = [];
    if (land && land.landing.entries.length) {
      specs.push({ key: "landing:" + land.name, title: "", continues: true,
                   links: land.landing.entries.map(function (e) { return { title: e.title, href: e.href, entry: true }; }) });
    }
    if ((land && land.landing.next) || (cur && cur.product.next)) {
      specs.push({ key: "next", title: DATA.nextStep.title, links: DATA.nextStep.links });
    }
    var want = specs.map(function (s) { return s.key; }).join(",");
    var asides = document.querySelectorAll("aside.dai-sidebar");
    for (var i = 0; i < asides.length; i++) {
      var aside = asides[i], nav = aside.querySelector(".dai-sidebar-content");
      if (!nav) continue;
      var old = aside.querySelector("[data-hij-extra]");
      if (old && old.getAttribute("data-hij-extra") === want && old.previousElementSibling === nav) continue;
      if (old) old.remove();
      if (!specs.length) continue;
      var proto = {
        page: nav.querySelector("a.dai-sidebar-page:not(.dai-sidebar-page-active)"),
        title: nav.querySelector(".dai-sidebar-group-title"),
      };
      var box = document.createElement("div");
      box.className = "hij-extra";
      box.setAttribute("data-hij-extra", want);
      specs.forEach(function (s) {
        var g = group(proto, s.title, s.links, s.key);
        if (s.continues) g.classList.add("hij-continues"); // continues the section's own list above
        box.appendChild(g);
      });
      nav.insertAdjacentElement("afterend", box);
    }
  }

  var queued = false;
  function apply() {
    queued = false;
    try { decorateTabs(); decorateSidebar(); } catch (err) { if (window.console) console.warn("[hij-nav]", err); }
  }
  function queue() { if (!queued) { queued = true; (window.requestAnimationFrame || setTimeout)(apply); } }
  new MutationObserver(queue).observe(document.body, { childList: true, subtree: true });
  window.addEventListener("popstate", queue);
  apply();
})();
